def open_gateway(self):
    """
    Obtain a socket-like object from `gateway`.

    :returns:
        A ``direct-tcpip`` `paramiko.channel.Channel`, if `gateway` was a
        `.Connection`; or a `~paramiko.proxy.ProxyCommand`, if `gateway`
        was a string.

    .. versionadded:: 2.0
    """
    if isinstance(self.gateway, str):
        # gateway is a ProxyCommand string
        proxy_command = ProxyCommand(self.gateway)
        return proxy_command.get_transport()
    elif isinstance(self.gateway, Connection):
        # gateway is another Connection object
        return self.gateway.client.get_transport()
